package com.crosscheck.repository; import com.crosscheck.model.Candidate;import org.springframework.data.jpa.repository.JpaRepository;import java.util.*; public interface CandidateRepository extends JpaRepository<Candidate,Long>{List<Candidate> findAllByOrderByCreatedAtDesc(); long countByRiskLevel(String riskLevel); boolean existsByEmailIgnoreCaseAndIdNot(String email,Long id); boolean existsByMobileNumberAndIdNot(String mobile,Long id);}
